import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { VRMLoaderPlugin } from '@pixiv/three-vrm';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';

// --- ELEMENTY UI ---
const settingsModal = document.getElementById('settings-modal');
const settingsBtn = document.getElementById('settings-btn');
const saveSettingsBtn = document.getElementById('save-settings-btn');
const apiKeyInput = document.getElementById('api-key');
const voiceSelect = document.getElementById('voice-select');
const systemPromptInput = document.getElementById('system-prompt');

const connectBtn = document.getElementById('connect-btn');
const connectText = document.getElementById('connect-text');
const micBtn = document.getElementById('mic-btn');
const micIcon = document.getElementById('mic-icon');
const speakerBtn = document.getElementById('speaker-btn');
const speakerIcon = document.getElementById('speaker-icon');
const statusDot = document.getElementById('status-dot');
const statusText = document.getElementById('status-text');

let isMutedMic = false;
let isMutedSpeaker = false;
let isConnected = false;

// --- Udostępnianie ekranu ---
let screenStream = null;
let screenInterval = null;
const screenCanvas = document.createElement('canvas');
const screenCtx = screenCanvas.getContext('2d');
const screenBtn = document.getElementById('screen-btn');
const screenIcon = document.getElementById('screen-icon');

// --- LOCAL STORAGE ---
function loadSettings() {
  const apiKey = localStorage.getItem('lisi_api_key') || '';
  const voice = localStorage.getItem('lisi_voice') || 'Aoede';
  const prompt = localStorage.getItem('lisi_prompt') || 'Jesteś Lisi, uroczą waifu-lisicą. Rozmawiasz na żywo po polsku.';

  if (apiKeyInput) apiKeyInput.value = apiKey;
  if (voiceSelect) voiceSelect.value = voice;
  if (systemPromptInput) systemPromptInput.value = prompt;

  if (!apiKey && settingsModal) settingsModal.classList.remove('hidden');
}

function saveSettings() {
  if (apiKeyInput) localStorage.setItem('lisi_api_key', apiKeyInput.value.trim());
  if (voiceSelect) localStorage.setItem('lisi_voice', voiceSelect.value);
  if (systemPromptInput) localStorage.setItem('lisi_prompt', systemPromptInput.value.trim());
  if (settingsModal) settingsModal.classList.add('hidden');
}

if (settingsBtn) settingsBtn.addEventListener('click', () => settingsModal.classList.remove('hidden'));
if (saveSettingsBtn) saveSettingsBtn.addEventListener('click', saveSettings);

// --- SCENA THREE.JS ---
const scene = new THREE.Scene();

const camera = new THREE.PerspectiveCamera(35, window.innerWidth / window.innerHeight, 0.1, 100);
camera.position.set(0, 1.25, 1.4);

const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));

const canvasElement = renderer.domElement;
canvasElement.style.position = 'fixed';
canvasElement.style.top = '0';
canvasElement.style.left = '0';
canvasElement.style.width = '100vw';
canvasElement.style.height = '100vh';
canvasElement.style.zIndex = '0';
canvasElement.style.pointerEvents = 'auto';

document.body.prepend(canvasElement);

// STEROWANIE KAMERĄ
const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 1.1, 0);
controls.enableDamping = true;
controls.dampingFactor = 0.05;

// WŁĄCZENIE PRZESUWANIA (PANNING)
controls.enablePan = true;
controls.panSpeed = 0.8;

// OGRANICZENIA PRZYBLIŻENIA I KĄTÓW
controls.minDistance = 0.8;
controls.maxDistance = 2.8;
controls.minPolarAngle = Math.PI * 0.25;
controls.maxPolarAngle = Math.PI * 0.6;

const ambientLight = new THREE.AmbientLight(0xffffff, 1.5);
scene.add(ambientLight);

const dirLight = new THREE.DirectionalLight(0xffffff, 2.0);
dirLight.position.set(2, 4, 3);
scene.add(dirLight);

let currentVrm = null;
let tailBones = [];

const loader = new GLTFLoader();
loader.register((parser) => new VRMLoaderPlugin(parser));

const VRM_URL = '/models/Lisi.vrm';

loader.load(
  VRM_URL,
  (gltf) => {
    currentVrm = gltf.userData.vrm;
    scene.add(currentVrm.scene);
    currentVrm.scene.rotation.y = Math.PI;
    setIdlePose(currentVrm);

    // WYŁĄCZENIE SPR INGBONE (żeby fizyka VRoid nie kasowała rotacji):
    if (currentVrm.springBoneManager) {
      currentVrm.springBoneManager.springBoneGroupList = [];
    }

    // Szukanie kości ogona
    tailBones = [];
    currentVrm.scene.traverse((object) => {
      if (object.isBone && object.name.toLowerCase().includes('foxtail')) {
        tailBones.push(object);
      }
    });

    tailBones.sort((a, b) => a.name.localeCompare(b.name));
    console.log(`🦊 Znaleziono kości ogona: ${tailBones.length}`, tailBones);

    window.currentVrm = currentVrm;
    window.tailBones = tailBones;
  },
  undefined,
  (err) => console.error('❌ Błąd ładowania VRM:', err)
);

function setIdlePose(vrm) {
  if (!vrm || !vrm.humanoid) return;
  const leftUpperArm = vrm.humanoid.getNormalizedBoneNode('leftUpperArm');
  const rightUpperArm = vrm.humanoid.getNormalizedBoneNode('rightUpperArm');
  const leftLowerArm = vrm.humanoid.getNormalizedBoneNode('leftLowerArm');
  const rightLowerArm = vrm.humanoid.getNormalizedBoneNode('rightLowerArm');

  if (leftUpperArm) leftUpperArm.rotation.z = Math.PI * 0.38;
  if (rightUpperArm) rightUpperArm.rotation.z = -Math.PI * 0.38;
  if (leftLowerArm) leftLowerArm.rotation.y = -Math.PI * 0.1;
  if (rightLowerArm) rightLowerArm.rotation.y = Math.PI * 0.1;
}

window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

// --- AUDIO & GEMINI LIVE ---
let ws = null;
let audioContext = null;
let audioAnalyser = null;
let micStream = null;
let micContext = null;
let nextPlayTime = 0;
let isSpeaking = false;

const LIVE_MODEL = "models/gemini-3.1-flash-live-preview";

function updateStatus(state, msg) {
  if (statusText) statusText.innerText = msg;
  if (!statusDot || !connectBtn || !connectText) return;

  if (state === 'connected') {
    statusDot.className = 'w-3 h-3 rounded-full bg-green-500 animate-pulse';
    connectText.innerText = 'Rozłącz';
    connectBtn.className = 'px-8 py-4 bg-red-600 hover:bg-red-700 font-bold rounded-full transition shadow-lg flex items-center space-x-2';
    isConnected = true;
  } else if (state === 'connecting') {
    statusDot.className = 'w-3 h-3 rounded-full bg-yellow-500 animate-ping';
    connectText.innerText = 'Łączenie...';
    isConnected = false;
  } else {
    statusDot.className = 'w-3 h-3 rounded-full bg-red-500';
    connectText.innerText = 'Połącz z Lisi';
    connectBtn.className = 'px-8 py-4 bg-gradient-to-r from-orange-500 to-amber-500 hover:from-orange-600 hover:to-amber-600 font-bold rounded-full transition shadow-lg flex items-center space-x-2';
    isConnected = false;
  }
}

function stopMicrophoneInput() {
  if (micStream) {
    micStream.getTracks().forEach(track => track.stop());
    micStream = null;
  }
  if (micContext) {
    micContext.close();
    micContext = null;
  }
}

async function startMicrophoneInput() {
  try {
    micStream = await navigator.mediaDevices.getUserMedia({ audio: true });
    micContext = new (window.AudioContext || window.webkitAudioContext)({ sampleRate: 16000 });

    const source = micContext.createMediaStreamSource(micStream);
    const processor = micContext.createScriptProcessor(2048, 1, 1);

    processor.onaudioprocess = (e) => {
      if (!ws || ws.readyState !== WebSocket.OPEN || isMutedMic) return;

      const inputData = e.inputBuffer.getChannelData(0);
      const pcm16 = new Int16Array(inputData.length);
      for (let i = 0; i < inputData.length; i++) {
        pcm16[i] = Math.max(-1, Math.min(1, inputData[i])) * 0x7FFF;
      }

      const bytes = new Uint8Array(pcm16.buffer);
      let binary = '';
      for (let i = 0; i < bytes.byteLength; i++) {
        binary += String.fromCharCode(bytes[i]);
      }
      const base64Audio = btoa(binary);

      const audioMessage = {
        realtimeInput: {
          audio: {
            mimeType: "audio/pcm;rate=16000",
            data: base64Audio
          }
        }
      };

      ws.send(JSON.stringify(audioMessage));
    };

    source.connect(processor);
    processor.connect(micContext.destination);
  } catch (err) {
    console.error('❌ Błąd mikrofonu:', err);
  }
}

async function toggleScreenShare() {
  if (screenStream) {
    stopScreenShare();
  } else {
    try {
      screenStream = await navigator.mediaDevices.getDisplayMedia({
        video: { frameRate: 1, width: 640, height: 360 }
      });

      const videoTrack = screenStream.getVideoTracks()[0];
      const videoElement = document.createElement('video');
      videoElement.srcObject = screenStream;
      await videoElement.play();

      if (screenIcon) screenIcon.className = "fa-solid fa-desktop text-xl text-green-400";

      videoTrack.onended = () => stopScreenShare();

      screenInterval = setInterval(() => {
        if (!ws || ws.readyState !== WebSocket.OPEN) return;

        screenCanvas.width = 640;
        screenCanvas.height = 360;
        screenCtx.drawImage(videoElement, 0, 0, 640, 360);

        const base64Image = screenCanvas.toDataURL('image/jpeg', 0.3).split(',')[1];

        const imageMessage = {
          realtimeInput: {
            video: {
              mimeType: "image/jpeg",
              data: base64Image
            }
          }
        };

        ws.send(JSON.stringify(imageMessage));
      }, 3000);

    } catch (err) {
      console.error("❌ Błąd udostępniania ekranu:", err);
      stopScreenShare();
    }
  }
}

function stopScreenShare() {
  if (screenInterval) {
    clearInterval(screenInterval);
    screenInterval = null;
  }
  if (screenStream) {
    screenStream.getTracks().forEach(track => track.stop());
    screenStream = null;
  }
  if (screenIcon) screenIcon.className = "fa-solid fa-desktop text-xl text-white";
}

async function connectToGeminiLive() {
  const apiKey = localStorage.getItem('lisi_api_key');
  if (!apiKey) {
    alert('Wpisz swój klucz API Gemini w ustawieniach!');
    if (settingsModal) settingsModal.classList.remove('hidden');
    return;
  }

  updateStatus('connecting', 'Łączenie...');

  try {
    if (!audioContext) {
      audioContext = new (window.AudioContext || window.webkitAudioContext)({ sampleRate: 24000 });
      audioAnalyser = audioContext.createAnalyser();
      audioAnalyser.fftSize = 64;
      audioAnalyser.connect(audioContext.destination);
    }
    if (audioContext.state === 'suspended') {
      await audioContext.resume();
    }

    const host = "generativelanguage.googleapis.com";
    const wsUrl = `wss://${host}/ws/google.ai.generativelanguage.v1beta.GenerativeService.BidiGenerateContent?key=${apiKey}`;

    ws = new WebSocket(wsUrl);

    ws.onopen = () => {
      console.log('⚡ Połączono z Gemini Live WebSocket!');
      updateStatus('connected', 'Połączono z Lisi');

      const voice = localStorage.getItem('lisi_voice') || 'Aoede';
      const systemPrompt = localStorage.getItem('lisi_prompt') || '';

      const setupMsg = {
        setup: {
          model: LIVE_MODEL,
          generationConfig: {
            responseModalities: ["AUDIO"],
            speechConfig: {
              voiceConfig: { prebuiltVoiceConfig: { voiceName: voice } }
            }
          },
          systemInstruction: {
            parts: [{ 
              text: systemPrompt + "\nWywołuj funkcję setEmotion(emotion, intensity) w trakcie wypowiedzi, gdy chcesz wyrazić uczucia twarzą. Dostępne emocje: happy, angry, sad, relaxed, surprised." 
            }]
          },
          tools: [
            {
              functionDeclarations: [
                {
                  name: "setEmotion",
                  description: "Ustawia ekspresję twarzy Lisi w zależności od kontekstu rozmowy.",
                  parameters: {
                    type: "OBJECT",
                    properties: {
                      emotion: {
                        type: "STRING",
                        description: "Nazwa emocji: happy, angry, sad, relaxed, surprised"
                      },
                      intensity: {
                        type: "NUMBER",
                        description: "Intensywność emocji od 0.0 do 1.0"
                      }
                    },
                    required: ["emotion"]
                  }
                }
              ]
            }
          ]
        }
      };

      ws.send(JSON.stringify(setupMsg));
      startMicrophoneInput();
    };

    ws.onmessage = async (event) => {
      try {
        let data;
        if (event.data instanceof Blob) {
          data = JSON.parse(await event.data.text());
        } else {
          data = JSON.parse(event.data);
        }

        const parts = data.serverContent?.modelTurn?.parts;
        if (parts) {
          for (const part of parts) {
            if (part.inlineData?.data && !isMutedSpeaker) {
              playPCMData(part.inlineData.data);
            }
          }
        }

        const toolCall = data.serverContent?.modelTurn?.parts?.find(p => p.functionCall);
        if (toolCall || data.toolCall) {
          const call = toolCall ? toolCall.functionCall : data.toolCall.functionCalls[0];
          if (call && call.name === "setEmotion") {
            const { emotion, intensity = 1.0 } = call.args;
            applyEmotionToVRM(emotion, intensity);

            const responseMsg = {
              toolResponse: {
                functionResponses: [
                  {
                    response: { output: { success: true } },
                    id: call.id
                  }
                ]
              }
            };
            ws.send(JSON.stringify(responseMsg));
          }
        }

      } catch (e) {
        console.error("Błąd przetwarzania wiadomości WebSocket:", e);
      }
    };

    ws.onerror = (err) => {
      console.error('❌ Błąd WebSocket:', err);
      updateStatus('disconnected', 'Błąd połączenia');
    };

    ws.onclose = (event) => {
      console.warn(`⚠️ WebSocket zamknięty! Kod: ${event.code}, Powód: "${event.reason}"`);
      stopMicrophoneInput();
      updateStatus('disconnected', 'Rozłączono');
    };

  } catch (err) {
    console.error("❌ Wyjątek podczas łączenia:", err);
    updateStatus('disconnected', 'Błąd połączenia');
  }
}

function disconnectGeminiLive() {
  if (ws) {
    ws.close();
    ws = null;
  }
  stopMicrophoneInput();
  stopScreenShare();
  updateStatus('disconnected', 'Rozłączono');
}

function playPCMData(base64PCM) {
  try {
    const binary = atob(base64PCM);
    const len = binary.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) bytes[i] = binary.charCodeAt(i);

    const int16 = new Int16Array(bytes.buffer);
    const float32 = new Float32Array(int16.length);
    for (let i = 0; i < int16.length; i++) {
      float32[i] = int16[i] / 32768.0;
    }

    const audioBuffer = audioContext.createBuffer(1, float32.length, 24000);
    audioBuffer.getChannelData(0).set(float32);

    const source = audioContext.createBufferSource();
    source.buffer = audioBuffer;
    source.connect(audioAnalyser);

    const now = audioContext.currentTime;
    if (nextPlayTime < now) nextPlayTime = now;

    source.start(nextPlayTime);
    nextPlayTime += audioBuffer.duration;
    isSpeaking = true;

    source.onended = () => {
      if (audioContext.currentTime >= nextPlayTime - 0.05) {
        isSpeaking = false;
      }
    };
  } catch (e) {
    console.error("Błąd odtwarzania audio:", e);
  }
}

if (connectBtn) {
  connectBtn.addEventListener('click', () => {
    if (isConnected) disconnectGeminiLive();
    else connectToGeminiLive();
  });
}

if (micBtn) {
  micBtn.addEventListener('click', () => {
    isMutedMic = !isMutedMic;
    if (micIcon) micIcon.className = isMutedMic ? "fa-solid fa-microphone-slash text-xl text-red-400" : "fa-solid fa-microphone text-xl text-white";
  });
}

if (speakerBtn) {
  speakerBtn.addEventListener('click', () => {
    isMutedSpeaker = !isMutedSpeaker;
    if (speakerIcon) speakerIcon.className = isMutedSpeaker ? "fa-solid fa-volume-xmark text-xl text-red-400" : "fa-solid fa-volume-high text-xl text-white";
  });
}

if (screenBtn) {
  screenBtn.addEventListener('click', toggleScreenShare);
}

// --- PĘTLA RENDEROWANIA ---
const clock = new THREE.Clock();
let nextBlinkTime = 0;

function animate() {
  requestAnimationFrame(animate);
  const deltaTime = clock.getDelta();
  const elapsedTime = clock.getElapsedTime();

  if (controls) controls.update();

  if (currentVrm) {
    currentVrm.update(deltaTime);
    setIdlePose(currentVrm);

    const spine = currentVrm.humanoid.getNormalizedBoneNode('spine');
    const head = currentVrm.humanoid.getNormalizedBoneNode('head');

    // Oddychanie i ruch głowy
    if (spine) spine.rotation.x = Math.sin(elapsedTime * 2) * 0.025;
    if (head) {
      head.rotation.y = Math.sin(elapsedTime * 0.8) * 0.03;
      if (isSpeaking) head.rotation.z = Math.sin(elapsedTime * 4) * 0.03;
    }

    // FALOWANIE OGONA (Z tyłu za plecami, wyłania się zza ramienia)
    if (tailBones && tailBones.length > 0) {
      tailBones.forEach((bone, index) => {
        const progress = index / tailBones.length;

        // Łagodne odchylenie w tył (mniej ujemny X zapobiega przenikaniu przez klatkę)
        const curlUp = -0.15 - Math.sin(progress * Math.PI) * 0.15;

        // Stałe odchylenie na bok (+0.25), żeby ogon wychodził z boku za plecami, a nie z klatki
        const sideOffset = 0.25 * progress;

        // Machanie na boki i góra-dół
        const waveY = Math.sin(elapsedTime * 2.5 - index * 0.4);
        const waveX = Math.cos(elapsedTime * 1.8 - index * 0.3);

        const intensity = 0.05 + progress * 0.90;

        // Aplikacja pozycji
        bone.rotation.x = curlUp + waveX * intensity * 0.2;
        bone.rotation.y = sideOffset + waveY * intensity;
        bone.rotation.z = Math.sin(elapsedTime * 2.0 - index * 0.3) * 0.05;

        bone.updateMatrix();
        bone.updateMatrixWorld(true);
      });
    }

    // Mruganie
    if (elapsedTime > nextBlinkTime) {
      currentVrm.expressionManager.setValue('blink', 1.0);
      setTimeout(() => {
        if (currentVrm) currentVrm.expressionManager.setValue('blink', 0.0);
      }, 140);
      nextBlinkTime = elapsedTime + Math.random() * 4 + 2;
    }

    // LIP-SYNC PROCEDURALNY
    let targetAa = 0;
    let targetIh = 0;
    let targetOu = 0;

    if (audioAnalyser && isSpeaking) {
      const dataArray = new Uint8Array(audioAnalyser.frequencyBinCount);
      audioAnalyser.getByteFrequencyData(dataArray);

      let sum = 0;
      for (let i = 0; i < dataArray.length; i++) sum += dataArray[i];
      const avg = sum / dataArray.length;

      if (avg > 8) {
        const volume = Math.min((avg - 8) / 35, 1.0);
        const flap = (Math.sin(elapsedTime * 25) * 0.4 + Math.sin(elapsedTime * 40) * 0.3 + 0.3);
        const mouthMouth = volume * Math.max(0, flap);

        const shapeSelector = Math.sin(elapsedTime * 10);
        if (shapeSelector > 0.2) {
          targetAa = mouthMouth * 0.8;
          targetIh = mouthMouth * 0.3;
        } else if (shapeSelector < -0.2) {
          targetOu = mouthMouth * 0.7;
        } else {
          targetIh = mouthMouth * 0.8;
        }
      }
    }

    const curAa = currentVrm.expressionManager.getValue('aa') || 0;
    const curIh = currentVrm.expressionManager.getValue('ih') || 0;
    const curOu = currentVrm.expressionManager.getValue('ou') || 0;

    currentVrm.expressionManager.setValue('aa', THREE.MathUtils.lerp(curAa, targetAa, 0.5));
    currentVrm.expressionManager.setValue('ih', THREE.MathUtils.lerp(curIh, targetIh, 0.5));
    currentVrm.expressionManager.setValue('ou', THREE.MathUtils.lerp(curOu, targetOu, 0.5));
  }

  renderer.render(scene, camera);
}

// OBSŁUGA KAMERKI
const btnCamera = document.getElementById('btn-camera');
const webcamVideo = document.getElementById('webcam-preview');
let cameraStream = null;

if (btnCamera && webcamVideo) {
  btnCamera.addEventListener('click', async () => {
    // Jeśli kamera jest włączona -> wyłącz
    if (cameraStream) {
      cameraStream.getTracks().forEach(track => track.stop());
      cameraStream = null;
      btnCamera.classList.remove('active');
      webcamVideo.style.display = 'none';
      return;
    }

    // Włączanie kamery
    try {
      cameraStream = await navigator.mediaDevices.getUserMedia({ 
        video: { width: 1280, height: 720 } 
      });

      webcamVideo.srcObject = cameraStream;
      btnCamera.classList.add('active');
      webcamVideo.style.display = 'block'; // Pokazuje okienko w rogu
    } catch (err) {
      console.error("Błąd dostępu do kamerki:", err);
    }
  });
}

let emotionTimeout = null;

function applyEmotionToVRM(emotionName, intensity = 1.0) {
  if (!currentVrm || !currentVrm.expressionManager) return;

  const validEmotions = ['happy', 'angry', 'sad', 'relaxed', 'surprised'];
  if (!validEmotions.includes(emotionName)) return;

  validEmotions.forEach(e => {
    currentVrm.expressionManager.setValue(e, 0.0);
  });

  currentVrm.expressionManager.setValue(emotionName, intensity);
  console.log(`🎭 Lisi zmienia emocję na: ${emotionName} (${intensity})`);

  if (emotionTimeout) clearTimeout(emotionTimeout);
  emotionTimeout = setTimeout(() => {
    if (currentVrm && currentVrm.expressionManager) {
      currentVrm.expressionManager.setValue(emotionName, 0.0);
    }
  }, 5000);
}

animate();
loadSettings();

* { box-sizing: border-box; margin: 0; padding: 0; }
body, html { width: 100%; height: 100%; overflow: hidden; font-family: sans-serif; background-color: #1a1a1a; color: #fff; }
#canvas-container { width: 100vw; height: 100vh; position: absolute; top: 0; left: 0; z-index: 1; }
.glass-panel { background: rgba(255, 255, 255, 0.1); backdrop-filter: blur(12px); border: 1px solid rgba(255, 255, 255, 0.2); border-radius: 16px; }
.icon-btn { position: absolute; top: 20px; right: 20px; z-index: 10; background: rgba(0, 0, 0, 0.5); border: none; font-size: 24px; padding: 10px; border-radius: 50%; cursor: pointer; color: white; }
.modal { position: absolute; top: 0; left: 0; width: 100vw; height: 100vh; z-index: 20; display: flex; justify-content: center; align-items: center; background: rgba(0, 0, 0, 0.6); }
.modal.hidden { display: none; }
.modal-content { width: 400px; padding: 24px; display: flex; flex-direction: column; gap: 12px; }
input, select, textarea { width: 100%; padding: 10px; border-radius: 8px; border: 1px solid rgba(255, 255, 255, 0.3); background: rgba(0, 0, 0, 0.4); color: #fff; }
.voice-controls { display: flex; gap: 8px; }
#chat-panel { position: absolute; bottom: 30px; left: 50%; transform: translateX(-50%); z-index: 10; width: 80%; max-width: 600px; padding: 12px; display: flex; gap: 10px; }
.primary-btn { padding: 10px 20px; border: none; border-radius: 8px; background: #ff7b00; color: white; font-weight: bold; cursor: pointer; }
/* Wyróżnienie aktywnego przycisku kamery */
.control-btn.active {
  background-color: #ff9000;
  color: #ffffff;
}

/* Okienko podglądu kamerki w prawym dolnym rogu */
#webcam-preview {
  position: absolute;
  bottom: 90px;
